window.aiwRequirementsPage={edit:id=>editArtefact(id),add:(type,links)=>editArtefact(null,null,type,links),link:preset=>linkDialog(null,preset),focus(id){if(get(id))ui.selected=id},get ghost(){return ui.ghost},get busy(){return ui.busy}};
