function intake(){const reqs=project.artefacts.filter(a=>a.type==='requirement'),current=project.handoff?.contentVersion===project.contentVersion;return `<article class="r-card r-intake"><div class="r-card-head"><div><p class="r-kicker">Same project / No re-entry</p><h2>Requirements received</h2></div><span class="r-badge ${current?'confirmed':'draft'}">${current?'Current handoff':'Handoff needs review'}</span></div><p>${current?`Revision ${project.contentVersion} carries ${reqs.length} requirements and ${project.handoff.openFindings} open findings into this intake.`:'You are viewing the latest Chapter 1 records. Complete a validation review and handoff to mark this revision as received.'}</p><div class="r-reference-note">This is the Chapter 2 receiving surface. The quality-scenario and driver-prioritisation studio will be developed in the next chapter build.</div><div class="r-intake-context"><div><h3>Business outcomes</h3>${project.artefacts.filter(a=>a.type==='outcome').map(a=>`<p><b>${a.id}</b> ${esc(a.title)}</p>`).join('')}</div><div><h3>Project intent</h3><p>${esc(project.brief.goal)}</p></div></div>${reqs.map(a=>`<details class="r-intake-record"><summary><span><small>${a.id} · ${a.priority}</small><strong>${esc(a.title)}</strong></span>${badge(a)}</summary><div><p>${esc(a.description)}</p><dl><div><dt>Owner</dt><dd>${esc(a.owner||'Missing')}</dd></div><div><dt>Source</dt><dd>${esc(a.source||'Missing')}</dd></div><div><dt>Acceptance</dt><dd>${esc(a.acceptance||'Missing — carried as an open finding.')}</dd></div><div><dt>Relationships</dt><dd>${related(project,a.id).map(r=>esc(r.from+' '+r.kind+' '+r.to)).join('<br>')||'No links recorded.'}</dd></div></dl><button class="r-btn" data-r-return="${a.id}">Open source requirement ${icon('arrow')}</button></div></details>`).join('')}<div class="r-actions">${btn('back-output','Review Chapter 1 output')}${btn('export-json',icon('download')+'Export shared project')}</div></article>`}
