function editBrief(){dialog('Review the project brief',`<form id="r-brief-form">${field('What problem are we solving?','problem',project.brief.problem,'textarea','rows="4" required maxlength="4000"')}${field('What outcome should this project achieve?','goal',project.brief.goal,'textarea','rows="3" required maxlength="4000"')}${field('Source / evidence','source',project.brief.source,'input','required maxlength="600"')}<label class="r-checkbox"><input name="confirmed" type="checkbox" ${project.brief.confirmed?'checked':''}>I have reviewed and confirm this brief.</label><p class="r-note">Editing a confirmed field resets confirmation until you review the change.</p><div class="r-dialog-actions">${btn('close-dialog','Cancel')}<button class="r-btn primary" type="submit">Save brief</button></div></form>`,'brief')}
function editArtefact(id=null,proposal=null,initialType=null,presetLinks=null){const old=id?get(id):null;const a=proposal?.record||old||{type:initialType||(ui.section==='journey'?'journey':ui.section==='context'?(ui.filter==='all'?'outcome':ui.filter):'requirement'),title:'',description:'',owner:'',source:'',priority:'Must',acceptance:'',confirmed:false,order:project.artefacts.filter(a=>a.type==='journey').length+1};dialogDraft={id:old?.id,origin:proposal?'suggestion':old?.origin||'user',links:proposal?.links||presetLinks||[]};const draft=dialogDraft;
  dialog(proposal?'Review & edit the ghost':old?`Edit ${old.id}`:'Add an artefact',`<form id="r-artefact-form"><div class="r-form-grid"><label class="r-field"><span>Artefact type</span><select name="type" id="r-record-type" ${old?'disabled':''}>${TYPES.map(t=>`<option value="${t.id}" ${a.type===t.id?'selected':''}>${t.name}</option>`).join('')}</select></label><label class="r-field"><span>Priority</span><select name="priority">${PRIORITIES.map(p=>`<option ${p===a.priority?'selected':''}>${p}</option>`).join('')}</select></label></div>${field('Title','title',a.title,'input','required maxlength="160"')}${field('Description / behaviour','description',a.description,'textarea','rows="3" maxlength="4000"')}<div class="r-form-grid">${field('Owner','owner',a.owner,'input','maxlength="180"')}${field('Source / evidence','source',a.source,'input','maxlength="600"')}</div><div id="r-acceptance-fields" ${a.type!=='requirement'?'hidden':''}>${field('Acceptance criteria','acceptance',a.acceptance,'textarea','rows="3" maxlength="4000" placeholder="Given a condition, when an action occurs, then an observable result…"')}</div><div id="r-scope-fields" ${a.type!=='scope'?'hidden':''}><label class="r-field"><span>Scope boundary</span><select name="scopeMode"><option value="in" ${a.scopeMode!=='out'?'selected':''}>In scope</option><option value="out" ${a.scopeMode==='out'?'selected':''}>Out of scope</option></select></label></div><div id="r-journey-fields" ${a.type!=='journey'?'hidden':''}>${field('Journey order','order',a.order||1,'input','type="number" min="1" max="999"')}</div><label class="r-checkbox"><input type="checkbox" name="confirmed" ${a.confirmed?'checked':''}>I have reviewed and confirm this record.</label><p class="r-note">${old?'The stable ID '+old.id+' will stay unchanged.':`A stable ID is assigned when you save.`} ${proposal?'This suggestion is editable and remains a draft until confirmed.':''}${!proposal&&!old&&presetLinks?.length?' Once saved it is connected: '+presetLinks.map(([f,k,t])=>esc((f==='new'?'this record':f)+' '+k+' '+(t==='new'?'this record':t))).join('; ')+'.':''}</p><div class="r-dialog-actions">${old?btn('delete-artefact','Remove artefact','danger',`data-remove-id="${old.id}"`):''}${btn('close-dialog','Cancel')}<button class="r-btn primary" type="submit">${proposal?'Apply edited proposal':'Save artefact'}</button></div></form>`,'artefact');dialogDraft=draft;
}
function linkDialog(finding=null,preset=null){const a=selected();const options=chosen=>project.artefacts.map(n=>`<option value="${n.id}" ${n.id===chosen?'selected':''}>${esc(n.id+' · '+n.title)}</option>`).join('');dialog('Connect two artefacts',`<form id="r-link-form"><label class="r-field"><span>From artefact</span><select name="from">${options(preset?.from||(finding?.code==='journey-link'?project.artefacts.find(n=>n.type==='journey')?.id:a?.id))}</select></label><label class="r-field"><span>Relationship</span><select name="kind">${LINK_TYPES.map(k=>`<option ${k===(preset?.kind||(finding?.code==='journey-link'?'requires':'delivers'))?'selected':''}>${k}</option>`).join('')}</select></label><label class="r-field"><span>To artefact</span><select name="to">${options(preset?.to||(finding?.code==='journey-link'?a?.id:project.artefacts.find(n=>n.type==='outcome'&&n.id!==a?.id)?.id))}</select></label><p class="r-note">Read the relationship from left to right: source → relationship → target.</p><div class="r-dialog-actions">${btn('close-dialog','Cancel')}<button class="r-btn primary" type="submit">Save relationship</button></div></form>`,'relationship')}
function previewProposal(id){const proposal=proposals(project,selected(),ui.tab).find(p=>p.id===id);if(!proposal){toast('This suggestion is no longer needed. Reopen Mind Factory for the current context.');return}closeDialog(true);ui.ghost=proposal;ui.tab='model';ui.focus=false;revealType(proposal.record.type);if(proposal.target)ui.selected=proposal.target;render();$('.r-ghost-bar')?.scrollIntoView({block:'start'});toast('Ghost preview only. Review and edit before applying.');}
function openGhost(){if(ui.ghost)editArtefact(ui.ghost.target||null,ui.ghost)}
function explainMenu(kind){
  const a=selected(),g=guidance(project,a,ui.tab,ui.section),ps=proposals(project,a,ui.tab);
  const context=ui.tab==='work'?(a?esc(a.id+' · '+a.title):ui.section==='brief'?'Project brief':'Project context'):a?esc(a.id+' · '+a.title):esc(project.name);
  const actionSets={work:`${a?`<button class="r-btn" data-r-edit="${a.id}">${icon('edit')}Edit this artefact</button>${btn('link',icon('link')+'Connect an artefact')}`:btn('edit-brief',icon('edit')+'Review the brief')}${btn('add',icon('plus')+'Add an artefact')}${btn('show-model',icon('model')+'Explore the model')}`,model:`${btn('trace','Trace the journey')}${btn('link',icon('link')+'Connect an artefact')}${a?`<button class="r-btn" data-r-edit="${a.id}">Edit ${a.id}</button>`:''}${btn('go-validate',icon('shield')+'Review findings')}`,validate:`${btn('run-checks-menu',icon('shield')+'Run checks','primary')}${a?`<button class="r-btn" data-r-edit="${a.id}">Edit ${a.id}</button>`:''}${btn('show-model',icon('model')+'Inspect relationships')}`,output:`${btn('export-json',icon('download')+'Export project JSON')}${btn('export-md',icon('file')+'Export requirements brief')}${btn('handoff','Review handoff','gold')}`};
  if(kind==='sol')dialog('Sol · Act on this context',`${evidenceAssistantLink('sol')}<p class="r-dialog-intro">${context} · ${ui.tab}</p><div class="r-reference-note">${esc(g.next)}</div><p>${esc(g.attention)}</p><div class="r-menu-actions">${actionSets[ui.tab]}</div>${ps[0]?`<h3>A suggested improvement</h3><p>${esc(ps[0].reason)}</p><button class="r-btn gold" data-r-proposal="${ps[0].id}">Preview editable ghost</button>`:''}`,'sol');
  else{const question={work:'What needs to be explicit before you confirm this record?',model:'Which assumption or missing relationship could change this journey?',validate:'What evidence would close an open question?',output:'What would the next chapter need to understand this requirement?'}[ui.tab];dialog('Mind Factory · Explore a better question',`${evidenceAssistantLink('mind')}<p class="r-dialog-intro">Chapter 1 / ${ui.tab} · ${context}</p><div class="r-reference-note">${question}</div>${ps.map(p=>`<article class="r-pattern"><h3>${esc(p.label)}</h3><p>${esc(p.reason)}</p><button class="r-btn gold" data-r-proposal="${p.id}">${icon('spark')}Preview on the map</button></article>`).join('')||'<p>No additional proposals match this context. Select an artefact to explore its assumptions.</p>'}<p class="r-note">These editable proposals use project rules. Live-generation status is shown in Sol.</p>`,'mind')}
}
function handoff(){if(ui.modal)closeDialog(true);if(project.handoff?.contentVersion===project.contentVersion){location.href=projectURL('/?chapter=2');return}const fs=findings(project),reqs=project.artefacts.filter(a=>a.type==='requirement');dialog('Carry the requirements forward',`<form id="r-handoff-form"><p>${reqs.length} requirements will be available in Chapter 2 with their existing IDs, owners, sources, acceptance criteria, and relationships.</p><div class="r-reference-note">${reqs.filter(a=>a.confirmed).length} of ${reqs.length} requirements are confirmed. ${fs.length} findings remain open. They will be included in the handoff.</div>${project.review?.contentVersion!==project.contentVersion?`<p>Run validation on the current revision before continuing.</p>${btn('go-validate','Go to validation','primary')}`:`${fs.length?'<label class="r-checkbox"><input type="checkbox" name="acknowledge" required>I acknowledge the open findings and will carry them forward for review.</label>':''}<div class="r-dialog-actions">${btn('close-dialog','Cancel')}<button class="r-btn primary" type="submit">Continue to Chapter 2 ${icon('arrow')}</button></div>`}</form>`,'handoff')}
async function download(markdown=false){try{const file=await exportProject(1,markdown?'md':'json');toast('Export prepared · '+file.filename+' · '+file.bytes.toLocaleString()+' bytes.')}catch(e){toast(e.message)}}

function hideTip(){clearTimeout(tipTimer);$('#cursor-tip').hidden=true;}
function showTip(el,event){if(!ui.cursor||window.innerWidth<700||event?.pointerType==='touch'||ui.modal)return;const a=get(el.dataset.rInsight);if(!a)return;clearTimeout(tipTimer);tipTimer=setTimeout(()=>{const g=guidance(project,a,ui.tab,ui.section),tip=$('#cursor-tip');tip.className='r-cursor-tip';tip.innerHTML=`<small>CHAPTER 01 / ${ui.tab.toUpperCase()} · ${a.id}</small><h3>${esc(a.title)}</h3><p>${esc(g.explanation)}</p><p><b>${esc(a.owner||'Owner missing')}</b> · ${related(project,a.id).length} relationships · ${status(a)}</p><p class="r-tip-attention">${esc(g.attention)}</p><small>${esc(g.next)} Select to pin details and explore an editable ghost.</small>`;tip.innerHTML+=`<small>${esc(evidenceCursorText(project,a.id))}</small>`;tip.hidden=false;const box=el.getBoundingClientRect(),x=event?.clientX??box.x+box.width/2,y=event?.clientY??box.y+box.height/2;tip.style.left=Math.max(8,Math.min(innerWidth-328,x+14))+'px';tip.style.top=Math.max(8,Math.min(innerHeight-tip.offsetHeight-8,y+14))+'px'},250)}
function next(id=null){ui.focus=false;if(ui.chapter===2)ui.chapter=1;const m=milestones(project).find(m=>m.id===id)||milestones(project).find(m=>!m.done);if(!m){location.href=projectURL('/?chapter=2');return}ui.tab=m.tab;if(m.filter){ui.section=m.filter;ui.filter='all';ui.query='';ui.selected=project.artefacts.find(a=>!a.confirmed&&(m.filter==='context'?!['journey','requirement'].includes(a.type):a.type===m.filter))?.id||null}if(ui.tab==='model'&&selected())revealType(selected().type);stop();render();$('#workspace').scrollIntoView({block:'start'});}
function navigateTab(tab){stop();ui.tab=tab;if(tab==='model'&&!selected())ui.selected=project.artefacts.find(a=>a.type==='requirement')?.id||project.artefacts[0]?.id||null;if(tab==='model'&&selected())revealType(selected().type);render();$('.r-tabs .active')?.focus()}
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-r-select]');if(!b||b.disabled||ui.busy)return;
  if(b.dataset.rPage){ui.page=Number(b.dataset.rPage);$('#r-record-list').innerHTML=recordList(filtered());return;}
  if(b.dataset.rReviewPage){ui.reviewPage=Number(b.dataset.rReviewPage);render();return;}
  if(b.dataset.rDomain!==undefined){ui.domain=b.dataset.rDomain;ui.page=1;render();return;}
  if(b.dataset.rChapter==='2'){location.href=projectURL('/?chapter=2');return}
  if(b.dataset.rChapter){if(ui.modal)closeDialog();ui.chapter=Number(b.dataset.rChapter);ui.menu=false;stop();render();return}
  if(b.dataset.rTab)return navigateTab(b.dataset.rTab);
  if(b.dataset.rSection){ui.section=b.dataset.rSection;ui.filter='all';ui.page=1;ui.query='';ui.selected=null;render();return}
  if(b.dataset.rMilestone)return next(b.dataset.rMilestone);
  if(b.dataset.rSelect)return select(b.dataset.rSelect,!!b.closest('#r-map'));
  if(b.dataset.rEdit)return editArtefact(b.dataset.rEdit);
  if(b.dataset.rProposal)return previewProposal(b.dataset.rProposal);
  if(b.hasAttribute('data-r-layers-all')){stop();ui.layers=ui.layers.length===chapterPerspectives[1].length?[]:chapterPerspectives[1].map(l=>l[0]);ui.tab='model';ui.menu=false;render();return}
  if(b.dataset.rLayer){ui.tab='model';ui.menu=false;stop();ui.layers=ui.layers.includes(b.dataset.rLayer)?ui.layers.filter(x=>x!==b.dataset.rLayer):[...ui.layers,b.dataset.rLayer];render();return}
  if(b.dataset.rTraceStep!==undefined){stop();return setTrace(Number(b.dataset.rTraceStep))}
  if(b.dataset.rMapResult){ui.mapQuery='';stop();select(b.dataset.rMapResult);render();return}
  if(b.dataset.rReviewFilter){ui.reviewFilter=b.dataset.rReviewFilter;ui.reviewPage=1;render();return}
  if(b.dataset.rReturn){ui.chapter=1;ui.tab='work';ui.section='requirement';ui.selected=b.dataset.rReturn;ui.query='';render();return}
  if(b.dataset.rFix){
    const f=findings(project).find(f=>f.id===b.dataset.rFix);if(!f)return;
    if(f.code==='missing-type')return editArtefact(null,null,f.artefactType);
    if(f.code==='broken-link'){const r=project.relationships.find(r=>r.id===f.relationshipId);return dialog('Repair a broken relationship',`<p>${esc(f.detail)}</p><p>Remove the obsolete link, then connect the correct artefacts from the Model tab.</p><div class="r-dialog-actions">${btn('close-dialog','Keep for review')}${btn('confirm-delete-link','Remove broken link','danger',`data-link-id="${r.id}"`)}</div>`,'delete-link')}
    if(f.artefactId==='brief')return editBrief();
    if(get(f.artefactId)){ui.selected=f.artefactId;if(['journey-link','outcome-link'].includes(f.code))return linkDialog(f);return editArtefact(f.artefactId)}
  }
  if(b.dataset.rDeleteLink){const r=project.relationships.find(r=>r.id===b.dataset.rDeleteLink);dialog('Remove this relationship?',`<p>${esc(r.from+' '+r.kind+' '+r.to)}</p><p>The artefacts will remain. You can reconnect them later.</p><div class="r-dialog-actions">${btn('close-dialog','Keep relationship')}${btn('confirm-delete-link','Remove relationship','danger',`data-link-id="${r.id}"`)}</div>`,'delete-link');return}
  switch(b.dataset.rAction){
    case'workbook':openIntake({store,onSaved:()=>{project=store.value.document;ui.section='requirement';ui.tab='work';render();toast('Workbook import saved. Review the source assertions and open findings.');}});break;
    case'source-row':openSourceRow(project,ui.selected);break;
    case'clear-domain':ui.domain='';ui.onlyGaps=false;ui.page=1;render();break;
    case'assurance':ui.tab='validate';ui.reviewFilter='source';ui.reviewPage=1;render();break;
    case'delivery-gaps':ui.onlyGaps=!ui.onlyGaps;ui.page=1;render();break;
    case'reload':load();break;
    case'menu':ui.menu=!ui.menu;render();break;
    case'next':next();break;
    case'edit-brief':editBrief();break;
    case'context':ui.section='context';ui.selected=null;ui.filter='all';ui.query='';render();break;
    case'add':editArtefact();break;
    case'link':linkDialog();break;
    case'sol':explainMenu('sol');break;
    case'mind':explainMenu('mind');break;
    case'proposal':previewProposal(b.dataset.proposalId);break;
    case'edit-ghost':openGhost();break;
    case'dismiss-ghost':ui.ghost=null;render();toast('Ghost dismissed. The project is unchanged.');break;
    case'focus':stop();if(!ui.selected){toast('Select an artefact to focus its relationships.');break}ui.focus=!ui.focus;render();break;
    case'cursor':ui.cursor=!ui.cursor;saveCursorPreference(ui.cursor);render();break;
    case'trace':if(ui.modal)closeDialog(true);toggleTrace();break;
    case'run-checks-menu':closeDialog(true);ui.tab='validate';await command('review',{},'Validation recorded for the current revision.');break;
    case'trace-next':stop();setTrace(ui.traceIndex+1);break;
    case'trace-back':stop();setTrace(ui.traceIndex-1);break;
    case'trace-reset':stop();setTrace(0);break;
    case'wide':ui.wide=!ui.wide;render();break;
    case'clear-map-search':ui.mapQuery='';render();$('#r-map-search')?.focus();break;
    case'validate':await command('review',{},'Validation recorded for the current revision.');break;
    case'go-validate':closeDialog(true);navigateTab('validate');break;
    case'show-model':closeDialog(true);navigateTab('model');break;
    case'handoff':handoff();break;
    case'back-output':ui.chapter=1;ui.tab='output';render();break;
    case'export-json':download();break;
    case'export-md':download(true);break;
    case'back-surface':closeContextPanel();break;
    case'close-dialog':closeDialog();break;
    case'keep-editing':$('#r-discard').hidden=true;$('.r-dialog input, .r-dialog textarea')?.focus();break;
    case'discard':closeDialog(true);break;
    case'delete-artefact':{const a=get(b.dataset.removeId);dialog('Remove '+a.id+'?',`<p>${esc(a.title)}</p><p>This removes the artefact and its ${related(project,a.id).length} relationships from the working project. Exports already downloaded remain unchanged.</p><div class="r-dialog-actions">${btn('close-dialog','Keep artefact')}${btn('confirm-delete','Remove artefact','danger',`data-remove-id="${a.id}"`)}</div>`,'delete');break}
    case'confirm-delete':if(await command('deleteArtefact',{id:b.dataset.removeId},'Artefact and its relationships removed.')){ui.selected=null;render()}break;
    case'confirm-delete-link':await command('deleteRelationship',{id:b.dataset.linkId},'Relationship removed.');break;
    case'refresh-conflict':try{project=(await store.load()).document;$('#r-form-error').innerHTML='Latest project loaded. Your form values are preserved; review and save again.';setSaving('Latest project loaded')}catch(err){toast(err.message)}break;
    case'about':dialog('Requirements with a clear trail',`<p>Chapter 1 connects a project brief, context, journey, and requirements. The bank-payment records are illustrative until you confirm them.</p><h3>Private project storage</h3><p>Saved records are stored with your signed-in project and can be reopened. Unsaved forms stay in the current tab. Concurrent edits are detected before overwriting another saved revision.</p><h3>Guidance and confirmation</h3><p>Cursor, Sol, and Mind Factory use explicit rules and the current project context. Ghost suggestions are editable proposals. Live-generation status is shown in Sol. Your confirmation records content review; it does not constitute governance approval.</p><h3>Chapter 2 handoff</h3><p>The receiving surface reads the same records, IDs, and relationships. Quality scenarios read the current requirements and stable IDs.</p>`,'about');break;
  }
});
document.addEventListener('submit',async e=>{if(!e.target.closest('.r-dialog'))return;e.preventDefault();const form=e.target,data=Object.fromEntries(new FormData(form));data.confirmed=form.elements.confirmed?.checked===true;
  if(form.id==='r-brief-form')await command('brief',data,'Project brief saved.');
  if(form.id==='r-artefact-form'){const d=dialogDraft||{};data.type=form.elements.type.value;if(d.id)data.id=d.id;data.origin=d.origin;data.links=d.links;ui.section=['journey','requirement'].includes(data.type)?data.type:'context';ui.filter='all';const ok=await command('artefact',data,'Artefact saved with its stable ID.');if(ok){ui.ghost=null;render()}}
  if(form.id==='r-link-form')await command('relationship',data,'Relationship saved to the shared model.');
  if(form.id==='r-handoff-form'){const ok=await command('handoff',{acknowledge:form.elements.acknowledge?.checked===true},'Requirements carried into Chapter 2.');if(ok){location.href=projectURL('/?chapter=2');}}
});
document.addEventListener('input',e=>{if(e.target.id==='r-map-search'){ui.mapQuery=e.target.value;$('#r-map-results').innerHTML=mapSearchResults();return}if(e.target.id==='r-search'){ui.query=e.target.value;ui.page=1;$('#r-record-list').innerHTML=recordList(filtered());refineWorkspace(ui.tab,{chapter:1,id:ui.selected});return}if(e.target.closest('.r-dialog form')){ui.dirty=true;if(e.target.name!=='confirmed'&&e.target.form?.elements.confirmed)e.target.form.elements.confirmed.checked=false}});
document.addEventListener('change',e=>{if(e.target.id==='r-context-filter'){ui.filter=e.target.value;$('#r-record-list').innerHTML=recordList(filtered());refineWorkspace(ui.tab,{chapter:1,id:ui.selected})}if(e.target.id==='r-record-type'){const t=e.target.value;$('#r-acceptance-fields').hidden=t!=='requirement';$('#r-scope-fields').hidden=t!=='scope';$('#r-journey-fields').hidden=t!=='journey'}});
document.addEventListener('pointerover',e=>{const el=e.target.closest('[data-r-insight]');if(el)showTip(el,e)});
document.addEventListener('pointerout',e=>{if(e.target.closest('[data-r-insight]'))hideTip()});
document.addEventListener('focusin',e=>{const el=e.target.closest('[data-r-insight]');if(el)showTip(el)});
document.addEventListener('focusout',e=>{if(e.target.closest('[data-r-insight]'))hideTip()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')hideTip();const el=e.target.closest('#r-map [data-r-select]');if(el&&(e.key==='Enter'||e.key===' ')){e.preventDefault();const id=el.dataset.rSelect;select(id,true);$('#r-map [data-r-select="'+id+'"]')?.focus({preventScroll:true})}});
window.addEventListener('resize',()=>{hideTip();clearTimeout(resizeTimer);resizeTimer=setTimeout(drawMap,150)});
window.addEventListener('beforeunload',e=>{if(ui.dirty||ui.busy){e.preventDefault();e.returnValue=''}});
await load();
if(params.get('intake')==='start')openIntake();

document.addEventListener('aiw:external-project',()=>{project=store.value.document;render();});
